'use strict';
const defaults={light:{foreground:'#243229',surface:'#FFFFFF',accent:'#405B38',onAccent:'#FFFFFF',hover:'#30462B',border:'#788373',error:'#B52D25',focus:'#7253A0'},dark:{foreground:'#E6EDDF',surface:'#20291F',accent:'#B7D59D',onAccent:'#1D2B16',hover:'#CBE6B4',border:'#829477',error:'#FF9E91',focus:'#C5AFF5'}};
let palettes=JSON.parse(JSON.stringify(defaults)),theme='light',state='default',format='css';
const names={foreground:['Foreground','body / label'],surface:['Surface','background'],accent:['Accent','button fill'],onAccent:['On accent','button label'],hover:['Hover accent','hover fill'],border:['Border','input edge'],error:['Error','text / border'],focus:['Focus','outer ring']};
const notes={default:'Editable specimens. Try typing and tabbing through each theme.',hover:'Forced hover styling on input and button. Real pointer hover works too.',focus:'Forced focus rings for comparison. Tab to inspect actual keyboard focus.',error:'Error applies to the input, its boundary and message. Button stays default.',disabled:'Input and button are inactive; their contrast is exempt. Headings remain active text.'};
const cssName=k=>k.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());
function tokens(){document.querySelector('#tokens').innerHTML=Object.entries(names).map(([k,[n,h]])=>`<label class="token"><span class="token-label">${n}<small>${h}</small></span><span class="token-input"><span class="swatch" style="background:${palettes[theme][k]}"></span><input data-token="${k}" aria-label="${n} HEX" aria-describedby="error-${k}" value="${palettes[theme][k]}" maxlength="7" spellcheck="false" autocomplete="off" aria-invalid="false"></span><span class="invalid" id="error-${k}">Use #RGB or #RRGGBB. Last valid color retained.</span></label>`).join('');document.querySelectorAll('[data-token]').forEach(input=>input.addEventListener('input',()=>{const color=Contrast.normalize(input.value);input.setAttribute('aria-invalid',String(!color));if(!color){document.querySelector('#status').textContent='Invalid color. Export keeps the last valid palette.';return}palettes[theme][input.dataset.token]=color;input.previousElementSibling.style.background=color;render();}));}
function render(){document.querySelector('#state-note').textContent=notes[state];const previews=document.querySelector('#previews');if(!previews.children.length){previews.innerHTML=['light','dark'].map(t=>`<article class="preview" data-preview="${t}"><div class="preview-label"><span>${t==='light'?'☀ LIGHT':'◐ DARK'}</span><span>SPECIMEN ${t==='light'?'A':'B'}</span></div><h3>A little more considered.</h3><p>Make room for the work that matters.</p><label class="sample-label" for="sample-${t}">Project name</label><input class="sample-input" id="sample-${t}" value="Field notes" aria-describedby="message-${t}"><div class="error-message" id="message-${t}"></div><button class="sample-button" type="button">Create project ↗</button></article>`).join('');previews.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#status').textContent='Preview only. No project or data was submitted.'}));}
for(const t of ['light','dark']){const el=previews.querySelector(`[data-preview="${t}"]`);Object.entries(palettes[t]).forEach(([k,v])=>el.style.setProperty('--'+cssName(k),v));el.dataset.state=state;const input=el.querySelector('input');input.disabled=state==='disabled';input.setAttribute('aria-invalid',String(state==='error'));el.querySelector('button').disabled=state==='disabled';el.querySelector('.error-message').textContent=state==='error'?'! A project with this name already exists.':'';}
const fill=state==='hover'?'hover':'accent';const pairs=[['Body & label','Normal text · ≥ 4.5:1','foreground','surface',4.5,false],['Button label','Normal text · ≥ 4.5:1','onAccent',fill,4.5,true],['Button boundary','UI boundary · ≥ 3:1',fill,'surface',3,true],['Input boundary','UI boundary · ≥ 3:1',state==='error'?'error':state==='hover'?'foreground':'border','surface',3,true]];
if(state==='focus')pairs.push(['Focus ring','Outer ring vs surface · ≥ 3:1','focus','surface',3,true]);if(state==='error')pairs.push(['Error message','Normal text · ≥ 4.5:1','error','surface',4.5,true]);
document.querySelector('#matrix').innerHTML='<div class="matrix-row header"><span>COLOR PAIR / TARGET</span><span style="text-align:right">LIGHT</span><span style="text-align:right">DARK</span></div>'+pairs.map(([title,sub,a,b,min,disabled])=>`<div class="matrix-row"><div>${title}<small>${sub}</small></div>${['light','dark'].map(t=>{const r=Contrast.ratio(palettes[t][a],palettes[t][b]),ex=state==='disabled'&&disabled,pass=Contrast.passes(r,min);return `<div class="result ${ex?'exempt':pass?'':'fail'}"><b>${ex?'—':r.toFixed(2)+':1'}</b><span>${ex?'EXEMPT':pass?'✓ PASS':'! REVIEW'}</span></div>`}).join('')}</div>`).join('');exportCode();}
function cssExport(){return ['/* StateLens: solid-color tokens. Review real components before shipping. */',...Object.entries(palettes).map(([t,p])=>`[data-theme="${t}"] {\n${Object.entries(p).map(([k,v])=>`  --${cssName(k)}: ${v};`).join('\n')}\n}`),'/* Reusable component rules (normal, hover, focus, error, disabled). */','.sl-card { background: var(--surface); color: var(--foreground); padding: 24px; border-radius: 12px; }','.sl-input { background: var(--surface); color: var(--foreground); border: 1px solid var(--border); padding: 10px; border-radius: 5px; }','.sl-button { background: var(--accent); color: var(--on-accent); border: 1px solid var(--accent); padding: 10px 16px; border-radius: 5px; }','.sl-button:hover { background: var(--hover); border-color: var(--hover); }','.sl-input:hover { border-color: var(--foreground); }','.sl-input:focus-visible, .sl-button:focus-visible { outline: 2px solid var(--focus); outline-offset: 3px; }','.sl-input[aria-invalid="true"] { border: 2px solid var(--error); }','.sl-error { color: var(--error); }','.sl-input:disabled, .sl-button:disabled { opacity: .4; cursor: not-allowed; }','.sl-button:disabled:hover { background: var(--accent); border-color: var(--accent); }','@media (prefers-reduced-motion: reduce) { .sl-input, .sl-button { transition: none; } }'].join('\n\n')}
function exportCode(){document.querySelector('#code').value=format==='css'?cssExport():JSON.stringify({name:'StateLens',version:'0.1.0',colorSpace:'sRGB',themes:palettes,thresholds:{normalText:4.5,largeText:3,nonText:3},notes:'Solid colors only. Disabled UI is exempt. Color checks are not a WCAG conformance audit.'},null,2)}
document.querySelectorAll('[data-theme]').forEach(b=>b.addEventListener('click',()=>{theme=b.dataset.theme;document.querySelectorAll('[data-theme]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));tokens();render();}));
document.querySelectorAll('[data-state]').forEach(b=>b.addEventListener('click',()=>{state=b.dataset.state;document.querySelectorAll('[data-state]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();}));
document.querySelectorAll('[data-format]').forEach(b=>b.addEventListener('click',()=>{format=b.dataset.format;document.querySelectorAll('[data-format]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));exportCode();}));
document.querySelector('#reset').addEventListener('click',()=>{palettes=JSON.parse(JSON.stringify(defaults));tokens();render();document.querySelector('#status').textContent='Both palettes reset to the original colors.'});
document.querySelector('#copy').addEventListener('click',async()=>{const code=document.querySelector('#code');try{await navigator.clipboard.writeText(code.value);document.querySelector('#status').textContent=`${format.toUpperCase()} copied. Both themes included.`}catch{code.focus();code.select();document.querySelector('#status').textContent='Copy unavailable here. Code selected: use Ctrl/Cmd+C.'}});
document.querySelector('#download').addEventListener('click',()=>{const blob=new Blob([document.querySelector('#code').value],{type:format==='css'?'text/css':'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`statelens-tokens.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#status').textContent=`${format.toUpperCase()} download requested.`});tokens();render();
